// Generated by Automated Quality Gate; review before merging.
const {
  add,
  subtract,
  multiply,
  divide,
  calculatePercentage,
  modulo,
  absoluteDifference
} = require('../src/math');

describe('math utility functions', () => {
  describe('add', () => {
    test('should add two positive numbers correctly', () => {
      expect(add(2, 3)).toBe(5);
    });

    test('should throw error for non-numeric input', () => {
      expect(() => add(1, '2')).toThrow(TypeError);
    });
  });

  describe('subtract', () => {
    test('should subtract two numbers correctly', () => {
      expect(subtract(10, 5)).toBe(5);
    });

    test('should normalize -0 to 0', () => {
      expect(subtract(5, 5)).toBe(0);
    });
  });

  describe('multiply', () => {
    test('should multiply two numbers correctly', () => {
      expect(multiply(3, 4)).toBe(12);
    });

    test('should throw error for non-finite numbers', () => {
      expect(() => multiply(1, Infinity)).toThrow('Inputs must be finite numbers');
    });
  });

  describe('divide', () => {
    test('should divide two numbers correctly', () => {
      expect(divide(10, 2)).toBe(5);
    });

    test('should throw error when dividing by zero', () => {
      expect(() => divide(10, 0)).toThrow('Cannot divide by zero');
    });
  });

  describe('calculatePercentage', () => {
    test('should return 50 for 5 out of 10', () => {
      expect(calculatePercentage(5, 10)).toBe(50);
    });

    test('should return 0 when total is 0', () => {
      expect(calculatePercentage(10, 0)).toBe(0);
    });
  });

  describe('modulo', () => {
    test('should calculate correct modulo', () => {
      expect(modulo(10, 3)).toBe(1);
    });

    test('should throw error when modulus is 0', () => {
      expect(() => modulo(10, 0)).toThrow('Cannot modulo by zero');
    });
  });

  describe('absoluteDifference', () => {
    test('should return positive difference', () => {
      expect(absoluteDifference(5, 10)).toBe(5);
      expect(absoluteDifference(10, 5)).toBe(5);
    });
  });
});
